&+\binom{6}{3}x^3(-\frac{1}{x})^3 \\
&+\binom{6}{4}x^2(-\frac{1}{x})^4 \\
&+\binom{6}{5}x^1(-\frac{1}{x})^5 \\
&+\binom{6}{6}x^0(-\frac{1}{x})^6
\end{align*}

